"""Tests for the shared econometrics: OLS, Newey–West, GRS, Fama–MacBeth."""

from __future__ import annotations

import numpy as np
import pandas as pd
import pytest

from goldman.analysis.regression import (
    chance_exceedances,
    fama_macbeth,
    grs_test,
    newey_west_lags,
    time_series_regression,
)


def _market_panel(seed: int, n_obs: int = 240, n_assets: int = 5, noise: float = 0.02):
    """Excess returns generated by a one-factor model with known alpha and beta."""
    rng = np.random.default_rng(seed)
    idx = pd.period_range("2000-01", periods=n_obs, freq="M")
    market = pd.DataFrame({"Mkt-RF": rng.normal(0.006, 0.045, n_obs)}, index=idx)
    betas = np.linspace(0.5, 1.5, n_assets)
    alphas = np.linspace(-0.002, 0.002, n_assets)
    eps = rng.normal(0.0, noise, (n_obs, n_assets))
    y = alphas + np.outer(market["Mkt-RF"], betas) + eps
    assets = [f"a{i}" for i in range(n_assets)]
    return pd.DataFrame(y, index=idx, columns=assets), market, alphas, betas


def test_time_series_regression_recovers_alpha_and_beta():
    excess, market, alphas, betas = _market_panel(0, noise=1e-5)
    fit = time_series_regression(excess, market)
    np.testing.assert_allclose(fit.params["alpha"], alphas, atol=1e-5)
    np.testing.assert_allclose(fit.params["Mkt-RF"], betas, atol=1e-4)
    assert (fit.r2 > 0.999).all()
    assert fit.n_obs == 240 and fit.n_assets == 5 and fit.df_resid == 238


def test_ols_tstats_match_textbook_formula():
    excess, market, _, _ = _market_panel(1)
    fit = time_series_regression(excess, market, hac_lags=0)
    y = excess["a2"].to_numpy()
    x = np.column_stack([np.ones(len(y)), market.to_numpy()])
    b = np.linalg.solve(x.T @ x, x.T @ y)
    e = y - x @ b
    cov = (e @ e / (len(y) - 2)) * np.linalg.inv(x.T @ x)
    np.testing.assert_allclose(fit.tstats.loc["a2"], b / np.sqrt(np.diag(cov)))


def test_newey_west_with_zero_lags_is_white_hc0():
    excess, market, _, _ = _market_panel(2)
    fit = time_series_regression(excess, market, hac_lags=0)
    y = excess["a0"].to_numpy()
    x = np.column_stack([np.ones(len(y)), market.to_numpy()])
    xtx_inv = np.linalg.inv(x.T @ x)
    e = y - x @ (xtx_inv @ x.T @ y)
    hc0 = xtx_inv @ (x.T * e**2) @ x @ xtx_inv
    expected = fit.params.loc["a0"].to_numpy() / np.sqrt(np.diag(hc0))
    np.testing.assert_allclose(fit.tstats_hac.loc["a0"], expected)
    assert fit.hac_lags == 0


def test_newey_west_lag_rule():
    assert newey_west_lags(100) == 4
    assert newey_west_lags(119) == 4
    assert newey_west_lags(20) == 2
    excess, market, _, _ = _market_panel(3, n_obs=119)
    assert time_series_regression(excess, market).hac_lags == 4


def test_time_series_regression_validates_inputs():
    excess, market, _, _ = _market_panel(4)
    with pytest.raises(ValueError, match="same index"):
        time_series_regression(excess.iloc[1:], market)
    broken = excess.copy()
    broken.iloc[0, 0] = np.nan
    with pytest.raises(ValueError, match="missing"):
        time_series_regression(broken, market)
    with pytest.raises(ValueError, match="observations"):
        time_series_regression(excess.iloc[:2], market.iloc[:2])


def test_grs_matches_unbiased_covariance_form():
    excess, market, _, _ = _market_panel(5, n_obs=120, n_assets=8)
    fit = time_series_regression(excess, market)
    t, n, k = 120, 8, 1
    resid = fit.resid.to_numpy()
    sigma_u = resid.T @ resid / (t - k - 1)
    f = market.to_numpy().ravel()
    sharpe2 = f.mean() ** 2 / f.var()  # ML variance
    a = fit.alpha.to_numpy()
    expected = (t / n) * ((t - n - k) / (t - k - 1)) * (a @ np.linalg.solve(sigma_u, a))
    expected /= 1 + sharpe2
    result = grs_test(fit)
    assert result.stat == pytest.approx(expected)
    assert (result.df_num, result.df_den) == (8, 111)
    assert 0.0 <= result.p_value <= 1.0


def test_grs_rejects_large_alphas_and_has_size_under_null():
    excess, market, _, _ = _market_panel(6, n_obs=240, n_assets=5, noise=0.01)
    shifted = excess + 0.01  # a 12% p.a. alpha on every asset
    assert grs_test(time_series_regression(shifted, market)).p_value < 1e-6

    rng = np.random.default_rng(7)
    idx = pd.RangeIndex(119)
    rejections = 0
    n_sims = 300
    for _ in range(n_sims):
        m = rng.normal(0.01, 0.045, 119)
        y = np.outer(m, rng.uniform(0.5, 1.5, 10)) + rng.normal(0, 0.05, (119, 10))
        fit = time_series_regression(
            pd.DataFrame(y, index=idx), pd.DataFrame({"m": m}, index=idx), hac_lags=0
        )
        rejections += grs_test(fit).p_value < 0.05
    assert 0.01 <= rejections / n_sims <= 0.10


def test_grs_needs_more_months_than_assets():
    excess, market, _, _ = _market_panel(8, n_obs=6, n_assets=5)
    with pytest.raises(ValueError, match="T > N"):
        grs_test(time_series_regression(excess, market))


def test_chance_exceedances_counts_and_expectation():
    tstats = pd.Series([0.1, -2.5, 2.1, 0.0, 1.9])
    out = chance_exceedances(tstats, df=100)
    assert out["observed |t|>2"] == 2
    assert out["n tests"] == 5
    assert out["P(|t|>2) per test"] == pytest.approx(0.0482, abs=1e-3)
    assert out["expected by chance"] == pytest.approx(5 * out["P(|t|>2) per test"])
    assert 0.0 < out["P(at least observed)"] < 0.1
    assert 0.0 < out["Bonferroni p (largest |t|)"] <= 1.0


def test_fama_macbeth_static_betas_equal_cross_sectional_ols():
    excess, market, _, betas = _market_panel(9, n_assets=8)
    beta_series = pd.Series(betas, index=excess.columns, name="beta")
    fm = fama_macbeth(excess, beta_series, market)
    x = np.column_stack([np.ones(8), betas])
    ols = np.linalg.lstsq(x, excess.mean().to_numpy(), rcond=None)[0]
    np.testing.assert_allclose(fm.gamma.to_numpy(), ols)
    assert list(fm.gamma.index) == ["const", "beta"]
    assert len(fm.gamma_t) == len(excess)
    assert 0.0 <= fm.r2_cross_section <= 1.0


def test_shanken_correction_inflates_intercept_error_only_with_factors():
    excess, market, _, betas = _market_panel(10, n_assets=8)
    beta_series = pd.Series(betas, index=excess.columns, name="beta")
    plain = fama_macbeth(excess, beta_series)
    corrected = fama_macbeth(excess, beta_series, market)
    np.testing.assert_allclose(plain.se_shanken, plain.se)
    assert corrected.se_shanken["const"] >= corrected.se["const"]
    np.testing.assert_allclose(corrected.tstats, corrected.gamma / corrected.se)
    np.testing.assert_allclose(
        corrected.tstats_shanken, corrected.gamma / corrected.se_shanken
    )
